pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant DEPOSITOR_ACCOUNT = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        bool callerIsDepositor
    ) public {
        vm.assume(_batcherHash != bytes32(0));

        // Record initial batcherHash
        bytes32 initialBatcherHash = c.batcherHash();

        // Call as either depositor or random caller
        if (callerIsDepositor) {
            vm.prank(DEPOSITOR_ACCOUNT);
        } else {
            vm.prank(address(0x1234));
        }

        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        bytes32 finalBatcherHash = c.batcherHash();

        // The rule: batcherHash only changes if called by depositor
        assertTrue(callerIsDepositor || finalBatcherHash == initialBatcherHash);
    }
}

